def _slug(a):
    print(slug.slugify(a.text, a.sep))
    return 0


@command("top", "print the most frequent words in the text",
         [("text", {}), ("--k", {"type": int, "default": 3, "help": "number of words"})])
def _top(a):
    for word, n in topwords.top_words(a.text, a.k):
        print(word, n)
    return 0


